const articles = $input.all().map(i => i.json);

// Date range
const now = new Date();
const weekAgo = new Date(now - 7 * 24 * 60 * 60 * 1000);
const fmt = d => new Date(d).toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
const fmtShort = d => new Date(d).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

// Group by category
const grouped = {};
for (const a of articles) {
  const cat = a.category || 'general';
  if (!grouped[cat]) grouped[cat] = [];
  grouped[cat].push(a);
}

// Build markdown
const lines = [
  '# 📰 AI News Weekly Digest',
  '',
  `**${fmt(weekAgo)} — ${fmt(now)}**`,
  '',
  `> ${articles.length} articles from ${new Set(articles.map(a => a.source)).size} sources`,
  '',
  '---',
  ''
];

const sorted = Object.entries(grouped).sort((a, b) => b[1].length - a[1].length);

for (const [cat, arts] of sorted) {
  const label = cat.charAt(0).toUpperCase() + cat.slice(1);
  lines.push(`## ${label} (${arts.length})`);
  lines.push('');

  for (const a of arts) {
    const date = a.published_at ? fmtShort(a.published_at) : 'Date N/A';
    const summary = a.summary 
      ? a.summary.slice(0, 200) + (a.summary.length > 200 ? '...' : '')
      : '_No summary available._';
    lines.push(`### [${a.title}](${a.url})`);
    lines.push('');
    lines.push(`📅 ${date} · 📡 ${a.source}`);
    lines.push('');
    lines.push(summary);
    lines.push('');
  }
  lines.push('---');
  lines.push('');
}

lines.push(`_Generated on ${fmt(now)} by AI News Digest._`);

return [{ json: { markdown: lines.join('\n'), articleCount: articles.length } }];
